mapper.update:
UPDATE employee
SET name = #{name},

        password = #{password},

    department_id = #{departmentId},
    post = #{post}
WHERE id = #{id}

mapper.select:
SELECT FROM employee e LEFT JOIN department d ON d.id = e.department_id WHERE 1 = 1
AND e.department_id = #{departmentId}
AND e.post = #{post}
ORDER BY e.id
